cat > src/cli/options.ts <<'EOF'
import { usageError } from "./errors.ts";

export interface OptionDef {
  /** The key the option is stored under. */
  name: string;
  short?: string;
  long?: string;
  takesValue?: boolean;
}

export interface ParsedOptions {
  /** Values given for each option, in order. A flag without a value records "". */
  options: Map<string, string[]>;
  positionals: string[];
}

/**
 * Parses arguments like the real git's parse-options: options may come after positionals,
 * short flags may be clustered (`-qb main`, `-bmain`), long options take `--name=value` or
 * `--name value`, and `--` ends the options. Unknown options are usage errors (exit code 129).
 */
export function parseOptions(args: readonly string[], defs: readonly OptionDef[]): ParsedOptions {
  const options = new Map<string, string[]>();
  const positionals: string[] = [];
  const record = (def: OptionDef, value: string): void => {
    const values = options.get(def.name) ?? [];
    values.push(value);
    options.set(def.name, values);
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i] as string;
    if (arg === "--") {
      positionals.push(...args.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      const name = eq < 0 ? arg.slice(2) : arg.slice(2, eq);
      const def = defs.find((d) => d.long === name);
      if (!def) throw usageError(`unknown option \`${name}'`);
      if (!def.takesValue) {
        if (eq >= 0) throw usageError(`option \`${name}' takes no value`);
        record(def, "");
      } else if (eq >= 0) {
        record(def, arg.slice(eq + 1));
      } else {
        if (i + 1 >= args.length) throw usageError(`option \`${name}' requires a value`);
        record(def, args[++i] as string);
      }
      continue;
    }
    if (arg.startsWith("-") && arg.length > 1) {
      for (let j = 1; j < arg.length; j++) {
        const ch = arg[j] as string;
        const def = defs.find((d) => d.short === ch);
        if (!def) throw usageError(`unknown switch \`${ch}'`);
        if (!def.takesValue) {
          record(def, "");
          continue;
        }
        if (j + 1 < arg.length) {
          record(def, arg.slice(j + 1));
        } else {
          if (i + 1 >= args.length) throw usageError(`switch \`${ch}' requires a value`);
          record(def, args[++i] as string);
        }
        break;
      }
      continue;
    }
    positionals.push(arg);
  }
  return { options, positionals };
}

/** Whether a flag was given at least once. */
export function hasOption(parsed: ParsedOptions, name: string): boolean {
  return parsed.options.has(name);
}

/** The last value given for an option. */
export function lastValue(parsed: ParsedOptions, name: string): string | undefined {
  return parsed.options.get(name)?.at(-1);
}
EOF

cat > src/cli/quote.ts <<'EOF'
const ESCAPES: Record<number, string> = {
  0x07: "\\a",
  0x08: "\\b",
  0x09: "\\t",
  0x0a: "\\n",
  0x0b: "\\v",
  0x0c: "\\f",
  0x0d: "\\r",
  0x22: '\\"',
  0x5c: "\\\\",
};

/**
 * Quotes a path the way the real git does with the default `core.quotePath=true`: if it contains
 * a double quote, a backslash, a control character, or a non-ASCII byte, it is wrapped in double
 * quotes with C-style escapes and octal bytes. With `quoteSpace`, a space also forces quoting
 * (as in `git status --porcelain`).
 */
export function quotePath(path: string, options: { quoteSpace?: boolean } = {}): string {
  const bytes = Buffer.from(path, "utf8");
  let needsQuotes = options.quoteSpace === true && path.includes(" ");
  let body = "";
  for (const byte of bytes) {
    const escape = ESCAPES[byte];
    if (escape !== undefined) {
      body += escape;
      needsQuotes = true;
    } else if (byte < 0x20 || byte >= 0x7f) {
      body += "\\" + byte.toString(8).padStart(3, "0");
      needsQuotes = true;
    } else {
      body += String.fromCharCode(byte);
    }
  }
  return needsQuotes ? `"${body}"` : path;
}
EOF
cat > src/cli/date.ts <<'EOF'
const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** Converts a timezone like "+0530" to minutes east of UTC. */
export function timezoneMinutes(tz: string): number {
  const match = /^([+-])(\d\d)(\d\d)$/.exec(tz);
  if (!match) return 0;
  const minutes = Number(match[2]) * 60 + Number(match[3]);
  return match[1] === "-" ? -minutes : minutes;
}

/** Formats a date like the real git's default date format: "Tue Nov 14 22:13:20 2023 +0000". */
export function formatDefaultDate(timestamp: number, tz: string): string {
  const date = new Date((timestamp + timezoneMinutes(tz) * 60) * 1000);
  const pad = (n: number): string => String(n).padStart(2, "0");
  const time = `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())}`;
  return `${WEEKDAYS[date.getUTCDay()]} ${MONTHS[date.getUTCMonth()]} ${date.getUTCDate()} ${time} ${date.getUTCFullYear()} ${tz}`;
}
