export interface Commit {
  tree: string;
  parents: string[];
  /** Identity lines as stored: "Name <email> 1700000000 +0000". */
  author: string;
  committer: string;
  message: string;
}

export function parseCommit(data: Buffer): Commit {
  const text = data.toString("utf8");
  const end = text.indexOf("\n\n");
  const headerText = end < 0 ? text : text.slice(0, end);
  const commit: Commit = { tree: "", parents: [], author: "", committer: "", message: end < 0 ? "" : text.slice(end + 2) };
  for (const line of headerText.split("\n")) {
    const space = line.indexOf(" ");
    const key = line.slice(0, space);
    const value = line.slice(space + 1);
    if (key === "tree") commit.tree = value;
    else if (key === "parent") commit.parents.push(value);
    else if (key === "author") commit.author = value;
    else if (key === "committer") commit.committer = value;
  }
  return commit;
}

export function serializeCommit(commit: Commit): Buffer {
  const lines = [`tree ${commit.tree}`, ...commit.parents.map((p) => `parent ${p}`)];
  lines.push(`author ${commit.author}`, `committer ${commit.committer}`);
  return Buffer.from(`${lines.join("\n")}\n\n${commit.message}`, "utf8");
}

