  const match = /^(.*?) ?<([^>]*)> ?(\d+)? ?([+-]\d+)?$/.exec(line);
  if (!match) return { name: line, email: "", timestamp: 0, tz: "+0000" };
  return { name: match[1] as string, email: match[2] as string, timestamp: Number(match[3] ?? 0), tz: match[4] ?? "+0000" };
}

